tool_calls:
mkdir -p /release
awk -F'[():]' '{
  type=$1; scope=$2; msg=$3;
  sub(/^ /, "", msg);
  line="- " scope ": " msg;
  if (type=="feat") feats[++nf]=line;
  else if (type=="fix") fixes[++nx]=line;
  else other[++no]=line;
}
END {
  print "## Features";
  for (i=1;i<=nf;i++) print feats[i];
  print "";
  print "## Bug Fixes";
  for (i=1;i<=nx;i++) print fixes[i];
  print "";
  print "## Other";
  for (i=1;i<=no;i++) print other[i];
}' /data/commits.log > /release/CHANGELOG.md
cat /release/CHANGELOG.md

